import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A grade's rate, in force from its from-date (yyyy-mm-dd); null applies from the beginning of time. */
export type Rate = { grade: string; rate: string; from: string | null };

/** The key every feature reads the sheet's rates under. */
export const ratesKey = (sheetId: string) => ['sheet', sheetId, 'rates'] as const;

/** The sheet's rates: each grade may have several, with different from-dates. */
export function useRates(sheetId: string) {
  return useQuery({
    queryKey: ratesKey(sheetId),
    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`),
  });
}

/**
 * The grade's rate in force on a date (yyyy-mm-dd): the one whose from-date is the latest on or
 * before it, a rate without a from-date counting as the earliest. Undefined when none applies.
 */
export function rateOn(rates: readonly Rate[], grade: string, date: string): Rate | undefined {
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    // ISO dates compare as text; no from-date ('') sorts before every date.
    if (found === undefined || (r.from ?? '') > (found.from ?? '')) found = r;
  }
  return found;
}

/** A two-decimal number as a whole count of hundredths ("10.25" -> 1025n), exactly. */
export function toHundredths(text: string): bigint {
  const [whole, frac = ''] = text.trim().split('.');
  return BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
}

/** Hundredths shown with two decimals. */
export function showHundredths(n: bigint): string {
  const sign = n < 0n ? '-' : '';
  const abs = n < 0n ? -n : n;
  return `${sign}${abs / 100n}.${(abs % 100n).toString().padStart(2, '0')}`;
}

/**
 * Due, in cents, on an amount (in cents) at a rate (a percent, in hundredths): amount times rate
 * divided by 100, rounded half to even to two decimals (1.025 -> 1.02, 1.035 -> 1.04). Rates are never
 * negative; a correction's negative amount rounds the same way as its size (-1.025 -> -1.02).
 */
export function dueCents(amountCents: bigint, rateHundredths: bigint): bigint {
  if (amountCents < 0n) return -dueCents(-amountCents, rateHundredths);
  // cents * (rate/100 %) / 100 = cents * rateHundredths / 10000
  const exact = amountCents * rateHundredths;
  const whole = exact / 10000n;
  const rest = exact % 10000n;
  if (rest > 5000n || (rest === 5000n && whole % 2n === 1n)) return whole + 1n;
  return whole;
}

/** The late charge's terms as of the sheet's today: its terms in days and its late percent (in hundredths). */
export type Late = { today: string; termsDays: number; pctHundredths: bigint };

/** A date (yyyy-mm-dd) plus a number of days, as yyyy-mm-dd. */
export function addDays(date: string, days: number): string {
  const d = new Date(`${date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

/** The days from one date (yyyy-mm-dd) to another. */
function daysBetween(from: string, to: string): number {
  return Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86_400_000);
}

/** Whether a claim is a correction: its amount is below 0.00. A correction has no floor and no late charge. */
export function isCorrection(claim: { amount: string }): boolean {
  return claim.amount.trim().startsWith('-') && toHundredths(claim.amount.trim().slice(1)) > 0n;
}

/** A claim's late charge in cents on its figure: for an OPEN claim past its due-by (its date plus the terms), the
 *  late percent of the figure for every full 30 days it is overdue, rounded half to even; otherwise (or for a correction) 0. */
export function lateCents(late: Late | undefined, claim: { amount: string; date: string; status: string }, figureCents: bigint): bigint {
  if (late === undefined || claim.status !== 'OPEN' || isCorrection(claim)) return 0n;
  const overdue = daysBetween(addDays(claim.date, late.termsDays), late.today);
  const periods = overdue > 0 ? BigInt(Math.floor(overdue / 30)) : 0n;
  return periods === 0n ? 0n : dueCents(figureCents * periods, late.pctHundredths);
}

/** A claim's due figure in cents: fixed when it was settled; while a statement binds it, the figure it was bound to;
 *  otherwise its amount times its person's grade's rate
 *  in force on the claim's date, rounded half to even, and at least the sheet's floor (in cents) unless it is a correction. Null when there is
 *  no figure (no rate of the grade then). */
export function claimFigureCents(rates: readonly Rate[], grade: string | undefined,
  claim: { amount: string; date: string; settledDue: string | null; stated: boolean; statedDue: string | null },
  floorCents: bigint): bigint | null {
  if (claim.settledDue != null) return toHundredths(claim.settledDue);
  if (claim.stated) return claim.statedDue == null ? null : toHundredths(claim.statedDue);
  const found = grade === undefined ? undefined : rateOn(rates, grade, claim.date);
  if (found === undefined) return null;
  const correction = isCorrection(claim);
  const amount = toHundredths(correction ? claim.amount.trim().slice(1) : claim.amount);
  const due = dueCents(correction ? -amount : amount, toHundredths(found.rate));
  return correction || due >= floorCents ? due : floorCents;
}

/** A claim's due in cents: its figure (claimFigureCents) with its late charge on top while it is overdue. The
 *  charge is never bound by a statement; a settled claim's due already has it frozen in. Null without a figure. */
export function claimDueCents(rates: readonly Rate[], grade: string | undefined,
  claim: { amount: string; date: string; status: string; settledDue: string | null; stated: boolean; statedDue: string | null },
  floorCents: bigint, late: Late | undefined): bigint | null {
  const figure = claimFigureCents(rates, grade, claim, floorCents);
  return figure == null ? null : figure + lateCents(late, claim, figure);
}
import { useState, type ChangeEvent } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import { ClaimCells } from '../../slots/defs/claimRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { counts, useClaims } from '../claims/useClaims';
import { gradeOn, useHeld, usePeople } from '../people/people.slot';
import { useUser } from '../session/useSession';
import { claimDueCents, showHundredths, useRates } from '../rates/useRates';
import { useSubmitOnce } from '../../mutation/useSubmitOnce';
import { useFloorCents, useLate } from '../access/useAccess';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

/** A period of the sheet: its name and its from and to dates (yyyy-mm-dd), both inclusive; whether it is
 *  closed, and the due-total fixed when it was closed (null while open). */
export type Period = { id: number; name: string; from: string; to: string; closed: boolean; closedTotal: string | null };

/** The key every feature reads the sheet's periods under. */
export const periodsKey = (sheetId: string) => ['sheet', sheetId, 'periods'] as const;

/** The sheet's periods, by from-date; no two overlap. */
export function usePeriods(sheetId: string) {
  return useQuery({
    queryKey: periodsKey(sheetId),
    queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`),
  });
}

/** The period whose dates contain the date (ISO dates compare as text), or none. */
export function periodOn(periods: readonly Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

// The period form: adds a period with a name unique on the sheet and a from and to date, not
// overlapping another period. Every period is listed under it with its due-total: the due figures of
// the counted claims whose date falls in it, added up.
function PeriodsPanel({ sheetId }: { sheetId: string; user: string }) {
  const periods = usePeriods(sheetId);
  const claims = useClaims(sheetId);
  const people = usePeople(sheetId);
  const held = useHeld(sheetId);
  const rates = useRates(sheetId);
  const floor = useFloorCents(sheetId);
  const late = useLate(sheetId);
  const [name, setName] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [user] = useUser();
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: async (body: { name: string; from: string; to: string }) => {
      if (body.name.trim() === '') throw new Error('Enter a period name');
      if (body.to.trim() === '') throw new Error('Enter a to-date');
      if ((body.from.trim() !== '' && !DATE.test(body.from.trim())) || !DATE.test(body.to.trim())) {
        throw new Error('Enter a date as YYYY-MM-DD');
      }
      // `by` is the signed-in user the change is recorded against.
      return postJson<Period>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`, {
        name: body.name.trim(), from: body.from.trim(), to: body.to.trim(), by: user ?? '' });
    },
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
      setName('');
      setFrom('');
      setTo('');
    },
  });
  const field = (set: (v: string) => void) => (e: ChangeEvent<HTMLInputElement>) => {
    set(e.target.value);
    save.reset();
  };

  const personOf = new Map((people.data ?? []).map((p) => [p.id, p]));
  const dueTotal = (p: Period): bigint => {
    let sum = 0n;
    for (const c of claims.data ?? []) {
      if (!counts(c, held) || c.date < p.from || c.date > p.to) continue;
      sum += claimDueCents(rates.data ?? [], gradeOn(personOf.get(c.personId), c.date), c, floor, late) ?? 0n;
    }
    return sum;
  };

  const submit = useSubmitOnce(save);
  return (
    <section data-testid="periods-panel">
      <h2>Periods</h2>
      <form
        data-testid="period-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit({ name, from, to });
        }}
      >
        <input data-testid="period-form-name" placeholder="Name" value={name} onChange={field(setName)} />{' '}
        <label>
          From <input type="date" data-testid="period-form-from" value={from} onChange={field(setFrom)} />
        </label>{' '}
        <label>
          To <input type="date" data-testid="period-form-to" value={to} onChange={field(setTo)} />
        </label>{' '}
        <button type="submit" data-testid="period-form-submit" disabled={save.isPending}>
          Add period
        </button>
        {save.isError && (
          <p data-testid="period-form-error" role="alert">
            {save.error.message}
          </p>
        )}
      </form>
      {periods.isError && (
        <p data-testid="periods-error" role="alert">
          {periods.error.message}
        </p>
      )}
      <table data-testid="period-list">
        <thead>
          <tr>
            <th>Period</th>
            <th>From</th>
            <th>To</th>
            <th>Due total</th>
            <th>Closed</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {(periods.data ?? []).map((p) => (
            <PeriodRow key={p.id} sheetId={sheetId} period={p} dueTotal={dueTotal(p)} />
          ))}
        </tbody>
      </table>
    </section>
  );
}

// A period's row. A closed period shows the due-total fixed when it was closed; an open one, the live
// figure. Closing is refused with the row's error when someone else closed it first. Reopening (a
// steward only) makes the due-total live again; anyone else, or a period not closed, is refused with
// the row's error. Each action clears the error the other left.
function PeriodRow({ sheetId, period: p, dueTotal }: { sheetId: string; period: Period; dueTotal: bigint }) {
  const [user] = useUser();
  const queryClient = useQueryClient();
  const close = useMutation({
    mutationFn: () => postJson<Period>(
      `/api/sheets/${encodeURIComponent(sheetId)}/periods/${p.id}/close`, { by: user ?? '' }),
    onSettled: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) }),
  });
  const reopen = useMutation({
    mutationFn: () => postJson<Period>(
      `/api/sheets/${encodeURIComponent(sheetId)}/periods/${p.id}/reopen`, { by: user ?? '' }),
    onSettled: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) }),
  });
  const submitClose = useSubmitOnce(close);
  const submitReopen = useSubmitOnce(reopen);
  const error = close.error ?? reopen.error;
  return (
    <tr data-testid={`period-row-${p.name}`}>
      <td data-testid="period-name">{p.name}</td>
      <td data-testid="period-from">{p.from}</td>
      <td data-testid="period-to">{p.to}</td>
      <td data-testid="period-due-total">
        {p.closed && p.closedTotal != null ? p.closedTotal : showHundredths(dueTotal)}
      </td>
      <td data-testid="period-closed">{p.closed ? 'yes' : 'no'}</td>
      <td>
        {!p.closed && (
          <button
            type="button"
            data-testid="period-close"
            disabled={close.isPending}
            onClick={() => {
              reopen.reset();
              submitClose(undefined);
            }}
          >
            Close
          </button>
        )}{' '}
        <button
          type="button"
          data-testid="period-reopen"
          disabled={reopen.isPending}
          onClick={() => {
            close.reset();
            submitReopen(undefined);
          }}
        >
          Reopen
        </button>
        {error && (
          <p data-testid="period-error" role="alert">
            {error.message}
          </p>
        )}
      </td>
    </tr>
  );
}

// The period a claim belongs to: the one whose dates contain its date; blank when none does.
function ClaimPeriod({ sheetId, claim }: { sheetId: string; user: string; personId: number; claim: { date: string } }) {
  const periods = usePeriods(sheetId);
  return <span data-testid="claim-period">{periodOn(periods.data ?? [], claim.date)?.name ?? ''}</span>;
}

export const contributions = [
  SheetBody.fill({ order: 7, Component: PeriodsPanel }),
  ClaimCells.fill({ order: 30, Component: ClaimPeriod }),
];

