      const due = claimDueCents(rates.data ?? [], grade, c, floor, late);
      kept ||= c.settledDue != null || (c.stated && c.statedDue != null) || (due != null && grade !== p.grade);
      sum += due ?? 0n;
    }
    totals.set(p.id, today.has(p.grade) || kept ? sum : null);
  }
